<script setup>
import { inject, ref, watch } from 'vue'
import { phases, levels, choices } from '../services/repository'
const props=defineProps({modelValue:Boolean,template:Object,roles:Array}),emit=defineEmits(['update:modelValue','saved'])
const repo=inject('repository'),form=ref({}),error=ref(''),busy=ref(false)
watch(()=>props.modelValue,open=>{if(open){form.value=props.template?JSON.parse(JSON.stringify(props.template)):{name:'',phase:'preop',level:'orange',recipients:[],description:'',enabled:true};error.value=''}})
async function save(){busy.value=true;error.value='';try{await repo.saveTemplate(form.value);emit('saved');emit('update:modelValue',false)}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><VDialog :model-value="modelValue" @update:model-value="emit('update:modelValue',$event)" max-width="640" :persistent="busy"><VCard><div class="section-head"><h2>{{template?'编辑事件模板':'新建事件模板'}}</h2><VBtn icon="tabler-x" variant="text" aria-label="关闭模板编辑" :disabled="busy" @click="emit('update:modelValue',false)"/></div><VCardText><form @submit.prevent="save"><VAlert v-if="error" type="error" variant="tonal" class="mb-5" role="alert">{{error}}</VAlert><div class="field"><label for="template-name">模板名称 <span class="text-error">*</span></label><VTextField id="template-name" v-model="form.name" maxlength="60" placeholder="例如：术前核查发现患者身份不符" counter="60"/></div><div class="form-grid"><div class="field"><label>发生阶段 *</label><VSelect aria-label="模板发生阶段" v-model="form.phase" :items="choices(phases)"/></div><div class="field"><label>告警等级 *</label><VSelect aria-label="模板告警等级" v-model="form.level" :items="choices(levels)"/></div></div><fieldset class="field" style="border:0"><legend class="caption mb-2">通知角色（至少选择一项）*</legend><div class="form-grid"><VCheckbox v-for="r in roles" :key="r" v-model="form.recipients" :label="r" :value="r" density="compact"/></div></fieldset><div class="field"><label for="template-description">填报说明（选填）</label><VTextarea id="template-description" v-model="form.description" maxlength="500" counter="500" rows="3" placeholder="说明适用场景与需要核对的信息"/></div><VSwitch v-model="form.enabled" label="启用此模板" class="mb-5"/><p class="caption muted mb-5">编辑或停用模板不会改变已填报记录的历史内容。</p><div class="action-row" style="justify-content:flex-end"><VBtn variant="tonal" color="secondary" :disabled="busy" @click="emit('update:modelValue',false)">取消</VBtn><VBtn type="submit" :loading="busy">保存模板</VBtn></div></form></VCardText></VCard></VDialog></template>
